exports.push([module.i, "\nhtml, body {\n    background-color: black !important;\n}\n", "", {"version":3,"sources":["/home/vinson/Projects/hkunited/nsl-quiz/resources/assets/js/components/competition/resources/assets/js/components/competition/Start.vue"],"names":[],"mappings":";AAqYA;IACA,mCAAA;CACA","file":"Start.vue","sourcesContent":["<template>\n    <div id=\"main_container\" class=\"container\">\n        <div class=\"row\">\n            <div class=\"col-md-12 question-order\">\n                <b>問題 {{ question.id }}</b>\n            </div>\n        </div>\n\n        <div class=\"row\">\n            <div class=\"col-md-12 question-title\">\n                <b :class=\"titleFontClass(question.name)\">{{ question.name }}</b>\n            </div>\n        </div>\n\n        <div class=\"row\">\n            <div class=\"col-md-12 question-progress\">\n                <div class=\"row\">\n                    <div class=\"col-md-11\">\n                        <div class=\"progress small-progress\">\n                            <div class=\"progress-bar\" role=\"progressbar\" :aria-valuenow=\"completePercent\" aria-valuemin=\"0\" aria-valuemax=\"100\" :style=\"'width:' + completePercent  + '%'\">\n                                <span class=\"sr-only\">{{completePercent}}% Complete</span>\n                            </div>\n                        </div>\n                    </div>\n\n                    <div class=\"col-md-1 counter\">\n                        {{ question.id }}/{{ totalQuestions }}\n                    </div>\n                </div>\n\n            </div>\n        </div>\n\n        <div class=\"row\">\n            <div class=\"col-md-offset-1 col-md-2\">\n            </div>\n            <div class=\"col-md-6 error-container text-center\">\n                <span v-show=\"showError\">\n                    {{ errorText }}\n                </span>\n            </div>\n            <div class=\"col-md-2 question-timer text-right\">\n                <b>計時</b> <span class=\"countdown\">{{ remainSeconds }}</span>\n            </div>\n        </div>\n\n        <div class=\"row question-options\">\n            <div v-for=\"(option, index) in question.options\"\n                :key=\"index\"\n                :class=\"'col-md-6 option-container' + fontClass(option) + ' ' + optionClass(option)\"\n                @click=\"setAnswer(option)\"\n            >\n                {{ option }}\n            </div>\n        </div>\n\n        <div class=\"row\">\n            <div class=\"col-md-12 text-center\">\n                <input type=\"button\" class=\"submit\" @click=\"submitAnswer(false)\">\n            </div>\n        </div>\n\n    </div>\n</template>\n\n<script>\nimport { captureMessage } from '@sentry/browser'\nimport Stat from '../mixins/stat.js'\nimport ResponseTime from '../mixins/response_time.js'\n\nexport default {\n    mixins: [Stat, ResponseTime],\n\n    created() {\n        this.sendStats()\n        this.initialize()\n    },\n\n    computed: {\n        isEmptyAnswer() {\n            return _.isEmpty(this.answer);\n        },\n\n        submitText() {\n            return this.submitting ? \"提交中...\" : \"提交\"\n        },\n\n        completePercent() {\n            let percent = parseInt((this.question.id / this.totalQuestions) * 100);\n\n            return percent;\n        }\n    },\n\n    data() {\n        return {\n            'page': 'competition-start',\n            'isLoading': false,\n            'showError': false,\n            'errorText': '請選擇答案',\n            'submitting': false,\n            'questionTimer': null,\n            'remainSeconds': \"--\",\n            'answer': null,\n            'correctAnswer': null,\n\n            // Paper\n            'secondsPerQuestion': 0,\n            'totalQuestions': 0,\n            'paperStartTime': '--',\n            'paperStartTimeOffset': 0,\n            \n            // Question\n            'question': {\n                'id': 0,\n                'multiple_select': false,\n                'paper_question_id': 1,\n                'name': '--',\n                'options': [\n                    '--',\n                    '--',\n                    '--',\n                    '--',\n                ],\n                'start_time': '2018-12-13 12:39:00',\n                'start_time_offset': 0\n            }\n        }\n    },\n\n    methods: {\n        initialize() {\n            axios.post(\"/api/initialize\")\n                .then((response) => {\n                    let data = response.data\n\n                    if (data.status == 200) {\n                        // Initialize data\n                        this.paperStartTime = data.paper_start_time\n                        this.paperStartTimeOffset = data.paper_start_time_offset\n                        this.secondsPerQuestion = data.seconds_per_questions\n                        this.totalQuestions = data.questions_per_paper\n\n                        this.getQuestion()\n\n                        return\n                    }\n                    \n                    if (data.status == 404) {\n                        // No assigned paper.\n                        captureMessage(`Check paper availability. Error: ${data.message}`)\n\n                        // window.location.href = '/';\n\n                        return\n                    }\n\n                    this.redirectTo()\n                })\n                .catch((error) => {\n                    console.log(error.message)\n                });\n        },\n\n        getQuestion() {\n            let startTime = moment()\n\n            axios.post(\"/api/question\")\n                .then((response) => {\n                    // Success\n                    if (response.data.status == 200) {\n                        this.resetAnswer()\n                        this.resetCorrectAnswer()\n\n                        this.setQuestion(response.data.question)\n                        this.setQuestionTimer()\n\n                        this.submitting = false\n\n                        return\n                    }\n\n                    // No processing paper || Paper timeout || no more question\n                    this.redirectTo();\n                })\n                .catch((error) => {\n                    console.log(error.message)\n                })\n                .then(() => {\n                    this.sendResponseTime(startTime)\n                })\n        },\n\n        setQuestion(data) {\n            // Random the order of options\n            data.options  = _.shuffle(data.options);\n\n            this.question = data;\n        },\n\n        setAnswer(option) {\n            this.resetError()\n\n            this.answer = option;\n        },\n\n        submitAnswer(force) {\n            if (this.submitting) {\n                return\n            }\n\n            if (force == false && this.answer == null) {\n                this.setError(\"請選擇答案\")\n\n                return\n            }\n            \n            this.submitting = true\n\n            this.resetError()\n\n            axios.post(\"/api/question/submit\", {\n                'paper_question_id': this.question.paper_question_id,\n                'answer': force ? null : (this.answer ? [this.answer] : null)\n            }).then((response) => {\n                this.clearQuestionTimer()\n                \n                let data = response.data\n\n                // Success.\n                if (data.status == 200) {\n                    this.setCorrectAnswer(data.correct_answer)\n\n                    if (!data.finished) {\n                        // Delay for showing correct answer.\n                        setTimeout(() => {\n                            this.getQuestion()\n                        }, 800)\n\n                        return\n                    }\n                }\n\n                // Paper finished || Paper id cache cleared by clean-timeout job || Paper timeout\n                this.redirectTo();\n            }).catch((error) => {\n                this.submitting = false\n\n                if (error.message == 'Network Error') {\n                    this.setError(\"請檢查網絡連線\")\n\n                    return\n                }\n                \n                if (error.response.status == 422) {\n                    let data = error.response.data\n\n                    if (data.status == 422 && data.message == 'Invalid request data.') {\n                        this.clearQuestionTimer()\n\n                        this.getQuestion()\n\n                        return\n                    }\n                }\n\n                this.setError(\"發生錯誤，請重試\")\n            })\n        },\n\n        setCorrectAnswer(answer) {\n            this.correctAnswer = answer\n        },\n\n        resetCorrectAnswer() {\n            this.correctAnswer = null\n        },\n\n        resetAnswer() {\n            this.answer = null;\n        },\n\n        setQuestionTimer() {\n            this.resetRemainSeconds()\n\n            this.questionTimer = setInterval(() => {\n                this.remainSeconds = this.remainSeconds - 1\n\n                if (this.remainSeconds < 0) {\n                    this.remainSeconds = 0\n                }\n            }, 1000)\n        },\n\n        resetRemainSeconds() {\n            this.remainSeconds = this.secondsPerQuestion - this.question.start_time_offset;\n            \n            if (this.remainSeconds < 0) {\n                this.remainSeconds = 0\n            }\n        },\n\n        clearQuestionTimer() {\n            clearInterval(this.questionTimer);\n        },\n        \n        redirectTo() {\n            window.location.href = '/competition/result';\n        },\n\n        titleFontClass(text) {\n            let length = text.length;\n            let size = 30;\n\n            if (length > 70) {\n                size = 25;\n            }\n\n            return ' title-font-size-' + size;\n        },\n\n        fontClass(option) {\n            return ' option-font-size-' + this.getOptimalFontSize(option)\n        },\n\n        optionClass(option) {\n            if (this.correctAnswer) {\n                if (this.correctAnswer == option) {\n                    return \"correct\";\n                } else {\n                    if (this.answer == option) {\n                        return \"wrong\";\n                    }\n                }\n            }\n\n            if (this.answer == option) {\n                return \"selected\";\n            }\n        },\n\n        getOptimalFontSize(text) {\n            // let length = text.length;\n\n            // if (length <= 11) {\n            //     return 25;\n            // }\n\n            // if (length > 11 && length <= 13) {\n            //     return 20;\n            // }\n\n            // if (length > 13 && length <= 16) {\n            //     return 18;\n            // }\n\n            // if (length > 16 && length <= 19) {\n            //     return 16;\n            // }\n\n            // return 14;\n\n            return 18;\n        },\n\n        setError(message) {\n            this.showError = true\n            this.errorText = message\n        },\n\n        resetError() {\n            this.showError = false\n        }\n    },\n\n    watch: {\n        // whenever question changes, this function will be executed.\n        remainSeconds: function (newSeconds, oldSeconds) {\n            if (newSeconds <= 0) {\n                console.log('auto submit answer');\n\n                this.submitAnswer(true)\n            }\n        }\n    },\n}\n</script>\n\n<style>\nhtml, body {\n    background-color: black !important;\n}\n</style>\n\n<style lang=\"scss\" scoped>\n$question-text-color : #3F4A50;\n\n#main_container {\n    width: 800px;\n    height: 600px;\n    background: url(\"/images/competition/bg.jpg\") no-repeat;\n\n    .question-order {\n        color: #FFFFFF;\n        font-size: 22px;\n        padding: 25px 0 0 0;\n        height: 85px;\n        text-align: center;\n    }\n\n    .question-title {\n        color: $question-text-color;\n        padding: 30px 110px;\n        height: 238px;\n    }\n\n    .title-font-size-25 {\n        font-size: 25px;\n    }\n\n    .title-font-size-30 {\n        font-size: 30px;\n    }\n\n    .question-progress {\n        padding: 0 110px;\n        height: 20px;\n\n        .progress-bar {\n            background: #231f20;\n        }\n\n        .small-progress {\n            height: 5px !important;\n        }\n\n        .counter {\n            position: absolute;\n            right: 90px;\n            bottom: 8px;\n            font-weight: bold;\n        }\n    }\n\n    .error-container {\n        color: red;\n        font-size: 20px;\n        height: 41px;\n        padding: 5px 0 0 0;\n\n        @keyframes color-change {\n            0% { color: red; }\n            50% { color: white; }\n            100% { color: red; }\n        }\n        \n        span {\n            -webkit-animation: color-change 1s infinite;\n            -moz-animation: color-change 1s infinite;\n            -o-animation: color-change 1s infinite;\n            -ms-animation: color-change 1s infinite;\n            animation: color-change 1s infinite;\n        }\n    }\n\n    .question-timer {\n        color: #FFFFFF;\n        font-size: 20px;\n        padding: 5px 13px 0 0;\n        height: 40px;\n        background: rgb(11,73,106);\n        width: 110px;\n\n        .countdown {\n            background-color: rgba(255,255,255,0.85);\n            color: #231f20;\n            padding: 0 6px;\n            border-radius: 5px;\n            margin: 0 1px;\n        }\n    }\n\n    .question-options {\n        height: 144px;\n\n        .option-container {\n            display: flex;\n            align-items: center;\n            justify-content: center;\n\n            width: 382px;\n            height: 78px;\n            margin: 0 8px;\n\n            text-align: center;\n\n            color: #FFFFFF;\n            background: url(\"/images/competition/option.png\") no-repeat;\n\n            cursor: pointer;\n        }\n\n        .selected {\n            background: url(\"/images/competition/option_active.png\") no-repeat !important;\n        }\n\n        .correct {\n            background: url(\"/images/competition/correct_answer.png\") no-repeat !important;\n        }\n\n        .wrong {\n            background: url(\"/images/competition/wrong_answer.png\") no-repeat !important;\n        }\n\n        .option-font-size-25 {\n            font-size: 25px;\n            padding: 18px 20px;\n        }\n\n        .option-font-size-20 {\n            font-size: 20px;\n            padding: 22px 20px;\n        }\n\n        .option-font-size-18 {\n            font-size: 18px;\n            padding: 0 40px;\n        }\n\n        .option-font-size-16 {\n            font-size: 16px;\n            padding: 18px 40px;\n        }\n\n        .option-font-size-14 {\n            font-size: 14px;\n            padding: 0 40px;\n        }\n    }\n\n    .submit {\n        background: url('/images/competition/submit.png') no-repeat;\n        width: 135px;\n        height: 53px;\n        border: none;\n\n        &:focus{\n            outline: none;\n        }\n    }\n}\n\n\n\n.urgent {\n    font-weight: bold;\n    color:red;\n}\n\n</style>\n\n\n"],"sourceRoot":""}]);

